      "summary": "首页 我国科研人员研制新型高频晶体管刷新全球纪录 分享到： 据中国科学院金属研究所8日消息，金属所等联合团队发明高频硅-石墨烯-锗势垒晶体管。 据介绍，随着5G的规模化部署与6G技术的前瞻性探索，物联网（IoT）、超高速传感及智能通信系统对晶体管的运行速度提出了前所未有的要求，即其截止频率需突破1太赫兹（THz）的关键",
